from scipy.ndimage import label, find_objects

def extract(grid):
 g=np.array(grid); objs=[]
 # color objects, non 0,2,4
 for col in sorted(set(g.flat)-{0,2,4}):
  lab,n=label(g==col, structure=np.ones((3,3)))
  for i,sl in enumerate(find_objects(lab),1):
   if sl is None: continue
   coords=np.argwhere(lab==i)
   color=col
   r0,c0=coords.min(0);r1,c1=coords.max(0)
   # reds inside bbox expanded by 1? assign nearest color distance
   reds=np.argwhere(g==2)
   sel=[]
   for p in reds:
    # nearest coord
    d=np.abs(coords-p).sum(1).min()
    sel.append((d,tuple(p)))
   # later nearest
   objs.append({'color':color,'coords':coords,'bbox':(r0,c0,r1,c1),'reds':[]})
 for p in np.argwhere(g==2):
  ds=[np.abs(o['coords']-p).sum(1).min() for o in objs]
  objs[int(np.argmin(ds))]['reds'].append(p)
 return objs

def transforms_out(inp,out):
 objs=extract(inp)
 ans={}
 for o in objs:
  col=o['color']; orig=set(map(tuple,o['coords']))
  dest=set(map(tuple,np.argwhere(np.array(out)==col)))
  # out can red overwrite some; only take coords that remain, ensure all
  rem=orig & dest if False else None
  shifts=[]
  for p in orig:
   for q in dest:
    dr,dc=q[0]-p[0],q[1]-p[1]
    shifted={(r+dr,c+dc) for r,c in orig}
    if shifted <= dest | set(map(tuple,np.argwhere(np.array(out)==2))): shifts.append((dr,dc))
  from collections import Counter
  if shifts: ans[col]=Counter(shifts).most_common(1)[0][0]
 return ans
