def sim(grid, distmetric='euclid', order='mindist', center=True):
 g=np.array(grid); objs=extract(g)
 yellow=next(o for o in objs if o['color']==4)
 others=[o for o in objs if o['color']!=4]
 for o in objs:
  o['solid']=set(map(tuple,o['coords']))
  o['red']=set(map(tuple,o['reds']))
  o['pos']=(0,0)
 def centers(o):
  ps=np.array(list(o['solid']|o['red'])); return ps.mean(0)+np.array(o['pos'])
 def dist(o):
  a=centers(o); b=centers(yellow)
  if distmetric=='manhattan': return np.abs(a-b).sum()
  if distmetric=='cheby': return np.abs(a-b).max()
  return ((a-b)**2).sum()
 if order=='mindist': others.sort(key=dist)
 placed=[yellow]
 for o in others:
  for step in range(100):
   dr,dc=np.sign(centers(yellow)-centers(o)).astype(int)
   cands=[(int(dr),int(dc))]
   if dr and dc: cands += [(int(dr),0),(0,int(dc))]
   # try any improving direction
   cands += [(a,b) for a in [-1,0,1] for b in [-1,0,1] if (a,b)!=(0,0)]
   seen=set(); good=[]
   for d in cands:
    if d in seen: continue
    seen.add(d)
    old=o['pos'];o['pos']=(old[0]+d[0],old[1]+d[1])
    solids=set(map(tuple,np.array(list(o['solid']))+np.array(o['pos'])))
    collision=any(solids & set(map(tuple,np.array(list(p['solid']))+np.array(p['pos']))) for p in placed)
    inside=all(0<=r<g.shape[0] and 0<=c<g.shape[1] for r,c in solids)
    if not collision and inside and dist(o)<dist(yellow) if False else True: pass
    if not collision and inside: good.append((dist(o),d))
    o['pos']=old
   if not good: break
   cur=dist(o); good=[x for x in good if x[0]<cur-1e-9]
   if not good: break
   _,d=min(good)
   o['pos']=(o['pos'][0]+d[0],o['pos'][1]+d[1])
  placed.append(o)
 out=np.zeros_like(g)
 for o in objs:
  for r,c in o['solid']:
   rr,cc=r+o['pos'][0],c+o['pos'][1];out[rr,cc]=o['color']
  for r,c in o['red']:
   rr,cc=r+o['pos'][0],c+o['pos'][1];out[rr,cc]=2
 return out.tolist(),{o['color']:o['pos'] for o in objs}
